// Nested in Miner Commander. Append the pure legacy parser helpers generated by --routes.
sealed class CanonicalRouteCompiler
{
    public const string Format = "C1";
    public string Mission, Result, SettingsRevision, SettingsSnapshot;
    public bool Ready;
    public readonly List<string> Warnings = new List<string>();
    string source;
    int cursor, lineStart, compileIndex, phase;
    bool anchorValid;
    Vector3D anchor, anchorForward, anchorUp;
    readonly List<string> records = new List<string>();
    readonly StringBuilder output = new StringBuilder();
    Vector3D _tickRcPosition;
    MatrixD _tickRcMatrix = MatrixD.Identity;
    Vector3D compilerGravity;
    const string mineAreaSkipMetaPrefix = "00;";
    struct DepthRange { public double Start, End; public DepthRange(double start,double end){Start=start;End=end;} }

    public void Begin(string mission, string immutableSource,string settingsRevision="",string settingsSnapshot="")
    {
        Mission=mission??"";source=immutableSource??"";Result=null;Ready=false;
        SettingsRevision=settingsRevision??"";SettingsSnapshot=settingsSnapshot??"";
        cursor=lineStart=compileIndex=phase=0;anchorValid=false;
        records.Clear();Warnings.Clear();output.Clear();
    }
    // Two bounded passes preserve the old loader's ability to discover the anchor
    // after an earlier source record. No active Pilot state changes during either pass.
    public bool Pump(int characterBudget=1024,int recordBudget=2)
    {
        if(Ready)return true;
        if(phase==0)
        {
            int characters=0,count=0;
            while(cursor<source.Length&&characters++<characterBudget&&count<recordBudget)
            {
                char c=source[cursor++];if(c!='\r'&&c!='\n')continue;
                Scan(source.Substring(lineStart,cursor-lineStart-1));lineStart=cursor;count++;
            }
            if(cursor<source.Length)return false;
            if(lineStart<source.Length){if(count>=recordBudget)return false;Scan(source.Substring(lineStart));lineStart=source.Length;return false;}
            if(characters>0)return false;
            if(anchorValid)output.Append("A|").Append(V(anchor)).Append('|').Append(V(anchorForward)).Append('|').Append(V(anchorUp)).Append('\n');
            phase=1;return false;
        }
        if(phase==1)
        {
            int count=0;
            while(compileIndex<records.Count&&count++<recordBudget)
            {
                string value=Compile(records[compileIndex]);
                if(value==null){Warnings.Add("Invalid path record #"+(compileIndex+1));value="invalid";}
                output.Append(value).Append('\n');compileIndex++;
            }
            if(compileIndex<records.Count)return false;
            phase=2;return false;
        }
        Result=output.ToString();Ready=true;return true;
    }
    void Scan(string raw)
    {
        string record=NormalizePathRecord(raw);if(string.IsNullOrWhiteSpace(record))return;
        Vector3D p,f,u;
        if(!anchorValid&&TryParseCarrierAnchorLine(record,out p,out f,out u))
        {anchorValid=true;anchor=p;anchorForward=f;anchorUp=u;return;}
        records.Add(record);
    }
    string V(Vector3D v){return NumberR(v.X)+":"+NumberR(v.Y)+":"+NumberR(v.Z);}
    string Navigation(Vector3D p,Vector3D f,Vector3D u,int flags){return "N|"+V(p)+"|"+V(f)+"|"+V(u)+"|"+flags;}
    string Area(Vector3D a,Vector3D b,Vector3D up,Vector3D forward,double depth,int mode)
    {return "M|"+V(a)+"|"+V(b)+"|"+V(up)+"|"+V(forward)+"|"+NumberR(depth)+"|"+mode;}
    string Compile(string record)
    {
        if(record.Equals("dock",StringComparison.OrdinalIgnoreCase)||record.Equals("undock",StringComparison.OrdinalIgnoreCase)||record.Equals("drillson",StringComparison.OrdinalIgnoreCase))return record.ToLowerInvariant();
        if(record.StartsWith("00;routeMeters:",StringComparison.OrdinalIgnoreCase))return record;
        if(IsMineAreaSkipMetaLine(record))return CompileMetadata(record);
        Vector3D p,f,u,a,b;double depth;
        if(record.StartsWith("minearea;",StringComparison.OrdinalIgnoreCase))
        {
            string[] parts=record.Split(';');
            if(parts.Length<5||!TryParsePoint(parts[1],out a)||!TryParsePoint(parts[2],out b)||!TryParseNumber(parts[4],out depth)||depth<=0)return null;
            string[] modes=parts[3].Split(',');int dynamicMode=0;
            if(modes.Length==2&&modes[0].Trim().Equals("Faceup",StringComparison.OrdinalIgnoreCase)&&modes[1].Trim().Equals("Faceforward",StringComparison.OrdinalIgnoreCase))
            {u=f=Vector3D.Zero;dynamicMode=1;}
            else if(!TryParseAreaOrientation(parts[3],a,b,out u,out f))return null;
            return "minearea;"+Area(a,b,u,f,depth,dynamicMode);
        }
        string nav=record.StartsWith("Nav;",StringComparison.OrdinalIgnoreCase)?record.Substring(4).Trim():record.StartsWith("GPS:",StringComparison.OrdinalIgnoreCase)?record:null;
        if(nav!=null)
        {
            if(!TryParseGpsCommand(nav,out p,out f,out u))return null;
            int flags=0;string[] parts=nav.Split('|');
            if(parts.Length>1)
            {
                string[] modes=parts[1].Split(new[]{','},StringSplitOptions.RemoveEmptyEntries);
                // Six valid numeric components already produced explicit axes. Other forms
                // retain the original dynamic orientation modes for Pilot-time evaluation.
                bool numeric=modes.Length==6;double number;
                for(int i=0;i<modes.Length&&numeric;i++)numeric=TryParseNumber(modes[i].Trim(),out number);
                if(!numeric)foreach(string mode in modes){if(mode.Trim().Equals("faceforward",StringComparison.OrdinalIgnoreCase))flags|=1;if(mode.Trim().Equals("faceup",StringComparison.OrdinalIgnoreCase))flags|=2;}
            }
            return "Nav;"+Navigation(p,f,u,flags);
        }
        if(!anchorValid)return null;
        bool reverse=record.StartsWith("reverse;",StringComparison.OrdinalIgnoreCase);
        if(reverse)record=record.Substring(8).Trim();
        if(LineLooksLikeMineArea(record))
        {
            if(!TryParseMineAreaLine(record,anchor,out a,out b,out u,out f,out depth))return null;
            return (reverse?"reverse;":"")+Area(a,b,u,f,depth,0);
        }
        return TryParsePathPointLine(record,anchor,out p,out f,out u)?(reverse?"reverse;":"")+Navigation(p,f,u,0):null;
    }
    string CompileMetadata(string record)
    {
        double h,w;int count;var skips=new List<int>();var depths=new List<double>();var ranges=new List<List<DepthRange>>();
        if(!TryParseMineAreaSkipMetaLine(record,out h,out w,out count,skips,depths,ranges))return "00;invalid";
        var b=new StringBuilder("00;C|");b.Append(NumberR(h)).Append('|').Append(NumberR(w)).Append('|').Append(count).Append('|');
        for(int i=0;i<skips.Count;i++){if(i>0)b.Append(',');b.Append(skips[i]);}b.Append('|');
        for(int i=0;i<depths.Count;i++){if(i>0)b.Append(',');b.Append(NumberR(depths[i]));}b.Append('|');
        // A header count preserves the distinction between absent ranges and all-empty ranges.
        b.Append(ranges.Count);
        for(int lane=0;lane<ranges.Count;lane++)foreach(var range in ranges[lane])b.Append(';').Append(lane).Append(',').Append(NumberR(range.Start)).Append(',').Append(NumberR(range.End));
        return b.ToString();
    }
    


bool IsMineAreaSkipMetaLine(string line)

{

    if (string.IsNullOrWhiteSpace(line))

        return false;

    string trimmed = line.Trim();

    return trimmed.StartsWith(mineAreaSkipMetaPrefix, StringComparison.OrdinalIgnoreCase);

}



bool TryParseMineAreaSkipMetaLine(

    string line,

    out double mineHeight,

    out double mineWidth,

    out int laneCount,

    List<int> skipLanes,

    List<double> laneDepths,

    List<List<DepthRange>> destructionRanges)

{

    mineHeight = 0;

    mineWidth = 0;

    laneCount = 0;

    skipLanes.Clear();

    laneDepths.Clear();

    destructionRanges.Clear();

    if (!IsMineAreaSkipMetaLine(line))

        return false;

    string trimmed = line.Trim();

    if (!TryParseCompactMineAreaSkipMetaPayload(trimmed.Substring(mineAreaSkipMetaPrefix.Length), out mineHeight, out mineWidth, out laneCount, skipLanes, laneDepths, destructionRanges))

        return false;

    SortLaneIndexes(skipLanes);

    return mineHeight > 0 && mineWidth > 0 && laneCount > 0;

}



bool TryParseCompactMineAreaSkipMetaPayload(

    string payload,

    out double mineHeight,

    out double mineWidth,

    out int laneCount,

    List<int> skipLanes,

    List<double> laneDepths,

    List<List<DepthRange>> destructionRanges)

{

    mineHeight = 0;

    mineWidth = 0;

    laneCount = 0;

    if (string.IsNullOrWhiteSpace(payload))

        return false;

    string[] parts = payload.Split(':');

    if (parts.Length < 1 || parts.Length > 4)

        return false;

    string[] header = parts[0].Split(',');

    if (header.Length != 3)

        return false;

    if (!TryParseNumber(header[0].Trim(), out mineHeight) || !TryParseNumber(header[1].Trim(), out mineWidth) || !int.TryParse(header[2].Trim(), out laneCount))

        return false;

    if (parts.Length >= 2 && !string.IsNullOrWhiteSpace(parts[1]))

    {

        string[] laneParts = parts[1].Split(',');

        for (int i = 0; i < laneParts.Length; i++)

            if (!TryAddCompactLaneToken(laneParts[i].Trim(), skipLanes))

                return false;

    }



    if (parts.Length >= 3)

    {

        string[] depthParts = parts[2].Split(',');

        if (depthParts.Length == laneCount)

        {

            for (int i = 0; i < depthParts.Length; i++)

            {

                double depth;

                if (!TryParseNumber(depthParts[i].Trim(), out depth) || depth < 0)

                {

                    laneDepths.Clear();

                    break;

                }



                laneDepths.Add(depth);

            }

        }

    }



    if (parts.Length >= 4)

    {

        string[] laneParts = parts[3].Split('|');

        if (laneParts.Length == laneCount)

        {

            for (int i = 0; i < laneParts.Length; i++)

            {

                List<DepthRange> ranges = new List<DepthRange>();

                if (TryParseDestructionRanges(laneParts[i].Trim(), ranges))

                    destructionRanges.Add(ranges);

                else

                    destructionRanges.Add(new List<DepthRange>());

            }

        }

    }



    return mineHeight > 0 && mineWidth > 0 && laneCount > 0;

}



bool TryParseDestructionRanges(string token, List<DepthRange> ranges)

{

    ranges.Clear();

    if (string.IsNullOrWhiteSpace(token) || token == ".")

        return true;

    string[] parts = token.Split('+');

    for (int i = 0; i < parts.Length; i++)

    {

        string part = parts[i].Trim();

        int dash = part.IndexOf('-');

        if (dash <= 0)

            return false;

        double start;

        double end;

        if (!TryParseNumber(part.Substring(0, dash).Trim(), out start) || !TryParseNumber(part.Substring(dash + 1).Trim(), out end) || start < 0)

            return false;

        if (end <= start)

            continue;

        ranges.Add(new DepthRange(start, end));

    }



    return true;

}



bool TryAddCompactLaneToken(string token, List<int> lanes)

{

    if (string.IsNullOrWhiteSpace(token))

        return true;

    int dash = token.IndexOf('-');

    if (dash > 0)

    {

        int first;

        int last;

        if (!int.TryParse(token.Substring(0, dash).Trim(), out first) || !int.TryParse(token.Substring(dash + 1).Trim(), out last) || first <= 0 || last < first)

            return false;

        for (int lane = first; lane <= last; lane++)

            AddLaneIndexUnique(lanes, lane - 1);

        return true;

    }



    int oneBasedLane;

    if (!int.TryParse(token.Trim(), out oneBasedLane) || oneBasedLane <= 0)

        return false;

    AddLaneIndexUnique(lanes, oneBasedLane - 1);

    return true;

}



bool LaneListContains(List<int> lanes, int laneIndex)

{

    for (int i = 0; i < lanes.Count; i++)

        if (lanes[i] == laneIndex)

            return true;

    return false;

}



void AddLaneIndexUnique(List<int> lanes, int laneIndex)

{

    if (laneIndex < 0 || LaneListContains(lanes, laneIndex))

        return;

    lanes.Add(laneIndex);

}



void SortLaneIndexes(List<int> lanes)

{

    lanes.Sort();

}



string NormalizePathRecord(string rawRecord)

{

    if (string.IsNullOrWhiteSpace(rawRecord))

        return "";

    string record = rawRecord.Trim();

    if (record.StartsWith("\"") && record.EndsWith("\"") && record.Length >= 2)

        record = record.Substring(1, record.Length - 2).Trim();

    return record;

}



bool TryParseAreaOrientation(string modeText, Vector3D pointA, Vector3D pointB, out Vector3D up, out Vector3D forward)

{

    up = Vector3D.Zero;

    forward = Vector3D.Zero;

    string[] modes = modeText.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

    if (modes.Length == 2)

    {

        string upMode = modes[0].Trim();

        string forwardMode = modes[1].Trim();

        if (!upMode.Equals("Faceup", StringComparison.OrdinalIgnoreCase) || !forwardMode.Equals("Faceforward", StringComparison.OrdinalIgnoreCase))

            return false;

        Vector3D gravity = compilerGravity;

        if (gravity.LengthSquared() > 0.001)

            up = Vector3D.Normalize(-gravity);

        else

            up = _tickRcMatrix.Up;

        Vector3D toward = pointB - pointA;

        toward = toward - Vector3D.Dot(toward, up) * up; // flatten into the area plane

        if (toward.LengthSquared() > 0.001)

            forward = Vector3D.Normalize(toward);

        else

            forward = _tickRcMatrix.Forward;

        return true;

    }



    if (modes.Length == 6)

    {

        double ux, uy, uz, fx, fy, fz;

        if (TryParseNumber(modes[0].Trim(), out ux) && TryParseNumber(modes[1].Trim(), out uy) && TryParseNumber(modes[2].Trim(), out uz) && TryParseNumber(modes[3].Trim(), out fx) && TryParseNumber(modes[4].Trim(), out fy) && TryParseNumber(modes[5].Trim(), out fz))

        {

            up = new Vector3D(ux, uy, uz);

            forward = new Vector3D(fx, fy, fz);

            if (up.LengthSquared() > 0.001)

                up = Vector3D.Normalize(up);

            if (forward.LengthSquared() > 0.001)

                forward = Vector3D.Normalize(forward);

            return up.LengthSquared() > 0.001 && forward.LengthSquared() > 0.001;

        }

    }



    return false;

}



bool TryParseVector3(string csv, out Vector3D value)

{

    value = Vector3D.Zero;

    string[] t = csv.Split(',');

    if (t.Length != 3)

        return false;

    double x, y, z;

    if (!TryParseNumber(t[0].Trim(), out x) || !TryParseNumber(t[1].Trim(), out y) || !TryParseNumber(t[2].Trim(), out z))

        return false;

    value = new Vector3D(x, y, z);

    return true;

}



bool TryParseAxisAngle(string s, out Vector3D forward, out Vector3D up)

{

    forward = new Vector3D(0, 0, -1);

    up = new Vector3D(0, 1, 0);

    if (string.IsNullOrWhiteSpace(s))

        return false;

    string[] t = s.Split(',');

    if (t.Length != 4)

        return false;

    double ax, ay, az, angle;

    if (!TryParseNumber(t[0].Trim(), out ax) || !TryParseNumber(t[1].Trim(), out ay) || !TryParseNumber(t[2].Trim(), out az) || !TryParseNumber(t[3].Trim(), out angle))

        return false;

    Vector3D axis = new Vector3D(ax, ay, az);

    if (Math.Abs(angle) < 1e-6 || axis.LengthSquared() < 1e-12)

        return true; // identity orientation

    axis = Vector3D.Normalize(axis);

    Quaternion q = Quaternion.CreateFromAxisAngle((Vector3)axis, (float)angle);

    forward = Vector3D.Normalize(Vector3D.Transform(new Vector3D(0, 0, -1), q));

    up = Vector3D.Normalize(Vector3D.Transform(new Vector3D(0, 1, 0), q));

    return true;

}



bool TryParseCarrierAnchorLine(string line, out Vector3D pos, out Vector3D forward, out Vector3D up)

{

    pos = Vector3D.Zero;

    forward = new Vector3D(0, 0, -1);

    up = new Vector3D(0, 1, 0);

    if (string.IsNullOrWhiteSpace(line))

        return false;

    string[] parts = line.Split(':');

    if (parts.Length != 2)

        return false;

    if (!TryParseVector3(parts[0], out pos))

        return false;

    return TryParseAxisAngle(parts[1], out forward, out up);

}



bool TryParsePathPointLine(string line, Vector3D anchor, out Vector3D pos, out Vector3D forward, out Vector3D up)

{

    pos = Vector3D.Zero;

    forward = new Vector3D(0, 0, -1);

    up = new Vector3D(0, 1, 0);

    if (string.IsNullOrWhiteSpace(line))

        return false;

    string[] parts = line.Split(':');

    if (parts.Length != 2)

        return false;

    Vector3D delta;

    if (!TryParseVector3(parts[0], out delta))

        return false;

    if (!TryParseAxisAngle(parts[1], out forward, out up))

        return false;

    pos = anchor + delta;

    return true;

}



// Mine area line format: dx,dy,dz : ax,ay,az,angle : w,h : depth

//   dx,dy,dz       — corner A as delta from the path-timer anchor position

//   ax,ay,az,angle — axis-angle rotation supplied by the plugin route

//   w,h            — corner B offset, projected into the recorded rotation's right/up plane

//   depth          — drill depth along the recorded rotation's forward

bool TryParseMineAreaLine(

    string line,

    Vector3D anchor,

    out Vector3D cornerA,

    out Vector3D cornerB,

    out Vector3D areaUp,

    out Vector3D areaForward,

    out double depth)

{

    cornerA = Vector3D.Zero;

    cornerB = Vector3D.Zero;

    areaUp = new Vector3D(0, 1, 0);

    areaForward = new Vector3D(0, 0, -1);

    depth = 0;

    if (string.IsNullOrWhiteSpace(line))

        return false;

    string[] parts = line.Split(':');

    if (parts.Length != 4)

        return false;

    Vector3D aDelta;

    if (!TryParseVector3(parts[0], out aDelta))

        return false;

    if (!TryParseAxisAngle(parts[1], out areaForward, out areaUp))

        return false;

    string[] wh = parts[2].Split(',');

    if (wh.Length != 2)

        return false;

    double w, h;

    if (!TryParseNumber(wh[0].Trim(), out w) || !TryParseNumber(wh[1].Trim(), out h))

        return false;

    if (!TryParseNumber(parts[3].Trim(), out depth))

        return false;

    cornerA = anchor + aDelta;

    areaForward = Vector3D.Normalize(areaForward);

    areaUp = Vector3D.Normalize(areaUp);

    Vector3D right = Vector3D.Cross(areaForward, areaUp);

    if (right.LengthSquared() > 1e-9)

        right = Vector3D.Normalize(right);

    cornerB = cornerA + right * w + areaUp * h;

    return true;

}



bool LineLooksLikeMineArea(string line)

{

    if (string.IsNullOrWhiteSpace(line))

        return false;

    int colons = 0;

    for (int i = 0; i < line.Length; i++)

        if (line[i] == ':' && ++colons > 3)

            return false;

    return colons == 3;

}



bool TryParsePoint(string text, out Vector3D value)

{

    value = Vector3D.Zero;

    if (string.IsNullOrWhiteSpace(text))

        return false;

    string t = text.Trim();

    if (t.StartsWith("GPS:", StringComparison.OrdinalIgnoreCase))

    {

        string[] parts = t.Split(':');

        if (parts.Length < 5)

            return false;

        double x, y, z;

        if (!TryParseNumber(parts[2], out x) || !TryParseNumber(parts[3], out y) || !TryParseNumber(parts[4], out z))

            return false;

        value = new Vector3D(x, y, z);

        return true;

    }



    return TryParseVector3(t, out value);

}



string NumberR(double value)

{

    return value.ToString("R", System.Globalization.CultureInfo.InvariantCulture);

}



bool TryParseNumber(string text, out double value)

{

    return double.TryParse(text, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out value);

}

bool TryParseGpsCommand(string command, out Vector3D gps, out Vector3D forward, out Vector3D up)

{

    gps = Vector3D.Zero;

    forward = Vector3D.Zero;

    up = Vector3D.Zero;

    string[] parts = command.Split('|');

    string gpsPart = parts[0];

    string[] gpsTokens = gpsPart.Split(':');

    if (gpsTokens.Length < 5)

        return false;

    double x, y, z;

    if (!TryParseNumber(gpsTokens[2], out x) || !TryParseNumber(gpsTokens[3], out y) || !TryParseNumber(gpsTokens[4], out z))

        return false;

    gps = new Vector3D(x, y, z);

    if (parts.Length > 1)

    {

        string[] modes = parts[1].Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

        if (modes.Length == 6)

        {

            double ux, uy, uz, fx, fy, fz;

            if (TryParseNumber(modes[0].Trim(), out ux) && TryParseNumber(modes[1].Trim(), out uy) && TryParseNumber(modes[2].Trim(), out uz) && TryParseNumber(modes[3].Trim(), out fx) && TryParseNumber(modes[4].Trim(), out fy) && TryParseNumber(modes[5].Trim(), out fz))

            {

                up = new Vector3D(ux, uy, uz);

                forward = new Vector3D(fx, fy, fz);

                if (up.LengthSquared() > 0.001)

                    up = Vector3D.Normalize(up);

                if (forward.LengthSquared() > 0.001)

                    forward = Vector3D.Normalize(forward);

                return true;

            }

        }



        Vector3D toTarget = gps - _tickRcPosition;

        foreach (string rawMode in modes)

        {

            string mode = rawMode.Trim().ToLower();

            if (mode == "faceforward")

            {

                if (toTarget.LengthSquared() > 0.001)

                    forward = Vector3D.Normalize(toTarget);

            }

            else if (mode == "faceup")

            {

                Vector3D gravity = compilerGravity;

                if (gravity.LengthSquared() > 0.001)

                    up = Vector3D.Normalize(-gravity);

                else

                    up = _tickRcMatrix.Up;

            }

        }

    }



    return true;

}
}
